#include <cstdio>
#include <cstring>
#include <cmath>
#include <cstdlib>
#include <vector>
#include <string>
#include <algorithm>
#include <queue>
#include <stack>
#include <deque>
#include <map>
#include <set>
#include <unordered_map>
#include <unordered_set>
#include <functional>
#include <numeric>
#include <sstream>
#include <iostream>
using namespace std;
int main(){string s;cin>>s;
vector<int>bars;
for(int i=0;i<(int)s.size();++i)if(s[i]=='|')bars.push_back(i);
if(bars.size()<2){printf("0\n");return 0;}
int c=0;
for(int i=bars[0]+1;i<bars[1];++i)if(s[i]=='*')++c;
printf("%d\n",c);return 0;}

